import json
from pathlib import Path
out={}
def add(a,name,purpose,details,inputs=None,outputs=None,corrupt=None):
 out[f'4:{a:04X}']={'name':name,'purpose':purpose,'details':details,'confidence':'proven'}
 for key,v in [('inputs',inputs),('outputs',outputs),('corrupt',corrupt)]:
  if v:out[f'4:{a:04X}'][key]=v
add(0x65A9,'PromptStateDisk','показать приглашение вставить диск с состояниями и дождаться клавиши','задаёт DE=70A7 со строкой приглашения и переходит на общую часть 65B1, она восстанавливает экран из банка 4 через 7311, заполняет нижнюю строку атрибутов 5AE0..5AFF значением 42, выводит текст через 70E4 в строке23, столбце5, затем IN (FE) с A=0 ожидает отпускания всех клавиш и нового нажатия',outputs=['диск может быть сменён пользователем, возврат после нового нажатия'],corrupt=['HL, DE, BC, AF'])
add(0x65AE,'PromptGameDisk','показать приглашение вставить диск с игрой и дождаться клавиши','задаёт DE=6D91, далее общая часть 65B1 восстанавливает экран из банка 4, выводит приглашение в нижней строке, ждёт полного отпускания клавиатуры и следующего нажатия, матрица опрашивается как NOT IN(00FE) AND1F',outputs=['возврат после нового нажатия клавиши'],corrupt=['HL, DE, BC, AF'])
add(0x6DBC,'CallTrdos','вызвать TR-DOS с временным переходом в IM 1','DI, IY=5C3A, входной AF сохраняется вокруг установки I=3F, затем IM1 и EI, вызывается 3D13 с исходными A и остальными параметрами, после возврата DI, I=60, IM2, EI, исходный IY не восстанавливается, A к выходу равен60',inputs=['A и остальные регистры по контракту функции TR-DOS в C'],outputs=['результат выбранной функции TR-DOS, IY=5C3A, I=60, IM2, прерывания разрешены'],corrupt=['регистры по контракту TR-DOS, AF, IY, I и режим прерываний'])
add(0x6DD6,'SelectStateDiskBank','запросить диск с состояниями и выбрать банк 1','вызывает 65A9 для приглашения и ожидания клавиши, затем A=1 и хвостовой JP5FA1 выбирает логический банк1, возврат выполняет RAMDRIVE',outputs=['выбран логический банк1'],corrupt=['HL, DE, BC, AF'])
add(0x6DE5,'SetStateExtension','установить тип файла состояния M и запросить диск состояний','записывает байт4D по DE, затем хвостовой JP65A9 показывает приглашение и ожидает клавиши',inputs=['DE адрес байта расширения файла'],outputs=['(DE)=M, приглашение завершено'],corrupt=['HL, DE, BC, AF'])
add(0x6DEE,'DrawGlyph','нарисовать символ шириной шесть пикселей с произвольным битовым сдвигом','сохраняет HL,DE,BC,AF,IY,IX и текущий логический банк, код переключения банка находится в изменяемых операндах6DFE и6E50, выбирает банк3 со шрифтом BF00+8*A, 6E5B получает экранный адрес и сдвиг X=6*C+2, 16-битная маска начинается03FF и сдвигается вправо с заполнением старших битов единицами, восемь байтов символа сдвигаются в пару D:E, каждый экранный байт заменяется по формуле (экран AND маска) OR символ, строки идут INC IXh, исходный банк и регистры восстанавливаются',inputs=['BC текстовая позиция, B строка знакомест, C шестипиксельный столбец, A код символа'],outputs=['восемь пиксельных строк символа нарисованы, регистры и логический банк сохранены'])
add(0x6E5B,'GlyphAddress','вычислить экранный адрес и битовый сдвиг шестипиксельного символа','первый адрес строки знакоместа B формируется через биты нелинейной ZX-развёртки, X=6*C+2, IX=4000+((B AND18)<<8)+((B AND7)<<5)+(X>>3), L=X AND7, это отдельная адресная процедура, сама экран не изменяет',inputs=['BC позиция, B строка0..23, C столбец шестипиксельного шрифта'],outputs=['IX адрес первого экранного байта, L сдвиг0..7, DE=X>>3'],corrupt=['HL, DE, AF, IX'])
add(0x6E88,'DrawGlyphEI','нарисовать символ с разрешением прерываний после переключения банка','сохраняет HL, записывает адрес70DF в оба изменяемых операнда6DFE и6E50, вызывает6DEE и восстанавливаетHL, обёртка70DF делает CALL5FA1 и EI, этот вариант используется обычным выводом текста',inputs=['BC текстовая позиция, A код символа'],outputs=['символ нарисован, регистры сохранены, операнды вызовов настроены на70DF'])
add(0x6E97,'DrawGlyphDirectPage','нарисовать символ без дополнительного EI в обёртке переключения банка','сохраняет HL, записывает прямой адрес5FA1 в операнды6DFE и6E50, вызывает6DEE, используется из обработчика прерывания6161, здесь нет EI обёртки70DF, сохранение и восстановление регистров выполняет6DEE',inputs=['BC текстовая позиция, A код символа'],outputs=['символ нарисован, регистры сохранены, операнды вызовов настроены на5FA1'])
add(0x6EA6,'DrawRawSprite','вывести непрозрачный прямоугольный спрайт с атрибутами','для каждого из D рядов знакомест 6EFA получает экранный адрес, восемь пиксельных строк копируются LDIR по E байт с INC D в адресе назначения, источник IX продвигается на8*E, после пикселей вычисляется5800+32*B+C и копируются D строки атрибутов шириной E с шагом32, ограничений экраном нет, все явно сохранённые регистры восстановлены',inputs=['BC левый верхний угол в знакоместах, D высота, E ширина в знакоместах, IX пиксели и следующие атрибуты'],outputs=['8*D*E пиксельных байтов и D*E атрибутов выведены, регистры сохранены'])
add(0x6EFA,'ScreenCharAddress','вычислить адрес верхней пиксельной строки знакоместа','HL=4000+((B AND18)<<8)+((B AND7)<<5)+C, BC сохраняется, это адрес для первой из восьми пиксельных строк заданного ряда знакомест',inputs=['BC позиция в знакоместах'],outputs=['HL экранный адрес'],corrupt=['HL, AF'])
add(0x6F15,'EditText','ввести строку ограниченной длины с мигающим курсором','сохраняет BC в6FA3, IX буфер в6FA5, максимальную длину A в6FA7, текущую позицию BC в61D2, ставит бит5 поля61D5 для прерывания, H хранит предел и L введённую длину, 6F81 обновляет строку, 6FA8 возвращает допустимый код, 0C удаляет предыдущий символ с заменой пробелом, 0D/0E завершают и сбрасывают бит5, остальные коды записываются пока L<H, выходное поле не получает нулевого терминатора',inputs=['BC позиция строки, A предел длины>0, IX буфер не короче A байтов, флаги61D5 задают допустимый алфавит'],outputs=['буфер содержит введённые символы, A код завершения0D/0E, L число введённых, H предел, прерывания разрешены'],corrupt=['HL, DE, AF, IX'])
add(0x6F81,'DrawEditBuffer','перерисовать поле редактирования и стереть символ за его концом','из6FA5 берёт буфер, из6FA3 позицию, из6FA7 число символов, рисует ровно эту длину через6E88 с увеличением столбца, затем один пробел после поля, входные DE,BC,AF сохраняются, HL не используется',inputs=['6FA3 позиция, 6FA5 буфер, 6FA7 длина>0'],outputs=['поле строки и следующий пробел нарисованы, регистры сохранены'])
add(0x6FA8,'ReadEditCharacter','дождаться допустимого символа для строкового ввода','обнуляет LAST_K5C08 и ждёт ненулевого значения от ROM-сканера, код07 переключает бит6 поля61D5 и продолжает ожидание, 0C/0D/0E возвращаются напрямую, бит4 разрешает только цифры и управляющие коды, без него допустимы пробел и латинские буквы, малые буквы переводятся в большие, бит6 включает перекодировку цифр по701A и букв по7024 в символы альтернативного алфавита',inputs=['биты4 и6 поля61D5, работающие прерывания с ROM-сканером'],outputs=['A допустимый код, HL и BC сохранены'],corrupt=['AF'])
add(0x7092,'LoadFile','загрузить именованный файл в заданную область через TR-DOS','копирует девять байт имени и расширения из HL в5CDD, записывает0в5D10, исходныйDE переноситвHL, C=0E, A=3 и хвостовойJP6DBC вызываетTR-DOS, длина выбирается из параметров файла',inputs=['HL имя8байтов и тип1байт, DE адрес загрузки'],outputs=['файл загружен черезTR-DOS, I=60, IM2'],corrupt=['HL, DE, BC, AF, IY'])
add(0x70DF,'PageAndEnable','выбрать логический банк и разрешить прерывания','вызывает RAMDRIVE5FA1 с входным A, затем EI и RET, это вариант переключения банка для обычного вывода текста',inputs=['A номер логического банка'],outputs=['банк выбран, прерывания разрешены'])
add(0x70E4,'DrawText','вывести строку с нулевым терминатором и переходами строк','читает символы изDE до0, обычный байт передаёт6E88 и увеличивает C, код0D потребляет следующий байт как новый столбецC и увеличивает строкуB, DE,BC,AF сохраняются, ограничения длины и экранного края отсутствуют',inputs=['DE строка, BC начальная текстовая позиция'],outputs=['текст выведен, регистры сохранены'])
add(0x7100,'ClearScreen','обнулить все пиксели и атрибуты ZX-экрана','записывает0по4000 и распространяет его LDIR с BC=1AFF из4000в4001, общий диапазон4000..5AFF составляет6912байтов, HL,DE,BC сохраняются, AF не изменяется инструкциями тела',outputs=['пиксели и атрибуты экрана нулевые, регистры сохранены'])
add(0x7132,'RandomRange','получить псевдослучайное число, масштабированное к входному пределу','состояние x,y,z хранится словами7190,7192,7194, обновление x=y, y=z, z=ROL16(x+y+z,1), новое z становится множителемBC, входнойDE сохраняетсяв718E и двоичными сдвигами умножаетсянаz в32-битный результат DE:HL, финальная проверка бита15 младшей половины увеличивает старшую половину для округления, поэтому DE=round(z*предел/65536), слово718E после16сдвиговнулевое, HL,BC,AF,IX сохраняются',inputs=['DE неотрицательный предел, состояние7190..7195 инициализировано'],outputs=['DE масштабированный результат, состояние генератора обновлено, HL,BC,AF,IX сохранены'])
expected={f'4:{f["address"]:04X}' for f in json.loads(Path('outputs/MYTHLAND/Docs/functions.json').read_text(encoding='utf-8')) if f['slot']==4 and 0x65a9<=f['address']<0x7196}
assert set(out)==expected,(sorted(set(out)-expected),sorted(expected-set(out)))
Path('work/kb/bl3_annotations.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
print('annotated',len(out),'missing',len(expected-set(out)))

